+            document.getElementById(fieldConfig[firstInvalidName].id).focus();
+            return;
+          }
+
+          state.status = {
+            tone: "success",
+            message: "Thanks. Your support request is ready to be reviewed.",
+          };
+          render();
+          form.reset();
+        });
+      }
