        color: inherit;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: -3rem;
        padding: 0.75rem 1rem;
        background: #ffffff;
        border-radius: 0.75rem;
        box-shadow: var(--shadow);
        text-decoration: none;
        z-index: 10;
      }

      .skip-link:focus {
        top: 1rem;
      }

