        backdrop-filter: blur(12px);
        border: 1px solid rgba(216, 226, 240, 0.9);
        border-radius: var(--radius-xl);
        box-shadow: var(--shadow);
        overflow: hidden;
      }

      .support-copy,
      .support-form-panel {
        padding: 2.5rem;
      }

      .support-copy {
        background:
          linear-gradient(160deg, rgba(36, 87, 255, 0.1), rgba(36, 87, 255, 0.02)),
          #f9fbff;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        margin: 0 0 1rem;
        padding: 0.4rem 0.8rem;
        border-radius: 999px;
        background: rgba(36, 87, 255, 0.1);
        color: var(--accent-strong);
        font-size: 0.9rem;
        font-weight: 700;
      }

      h1 {
        margin: 0 0 1rem;
        font-size: clamp(2rem, 5vw, 3rem);
        line-height: 1.05;
      }

      .lead {
        margin: 0 0 1.5rem;
        color: var(--text-secondary);
        font-size: 1.05rem;
        line-height: 1.6;
      }

      .feature-list {
        margin: 0;
        padding: 0;
        list-style: none;
        display: grid;
        gap: 0.9rem;
      }

      .feature-list li {
        display: flex;
        gap: 0.75rem;
        align-items: flex-start;
        color: var(--text-secondary);
      }

      .feature-list strong {
        color: var(--text-primary);
      }

      .feature-dot {
        width: 0.8rem;
        height: 0.8rem;
        border-radius: 999px;
        background: linear-gradient(135deg, var(--accent), #7c9cff);
        margin-top: 0.4rem;
        flex: 0 0 auto;
      }

      .support-form-panel {
        background: var(--panel-bg);
      }

      .panel-title {
        margin: 0 0 0.5rem;
        font-size: 1.5rem;
      }

      .panel-copy {
        margin: 0 0 1.5rem;
        color: var(--text-secondary);
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 1.1rem;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
      }

      label {
        font-weight: 700;
        font-size: 0.95rem;
      }

      .required-indicator {
        color: var(--error);
      }

      input {
        width: 100%;
        padding: 0.9rem 1rem;
        border: 1px solid #b9c8db;
        border-radius: var(--radius-md);
        font: inherit;
        color: var(--text-primary);
        background: #ffffff;
        transition: border-color 0.2s ease, box-shadow 0.2s ease;
      }

      input::placeholder {
        color: #70829f;
      }

      input:focus {
        outline: 2px solid transparent;
        border-color: var(--accent);
        box-shadow: 0 0 0 4px rgba(36, 87, 255, 0.18);
      }

      .helper-text,
      .error-text {
        margin: 0;
        font-size: 0.92rem;
        line-height: 1.4;
      }

      .helper-text {
        color: var(--text-secondary);
      }

      .error-text {
        color: var(--error);
      }

      input[aria-invalid="true"] {
        border-color: var(--error);
        background: var(--error-bg);
      }

      .status-message {
        min-height: 1.5rem;
        margin: 0;
        padding: 0.85rem 1rem;
        border-radius: var(--radius-md);
        font-weight: 600;
      }

      .status-message:empty {
        display: none;
      }

      .status-message.success {
        background: var(--success-bg);
        color: var(--success-text);
      }

      .status-message.error {
        background: var(--error-bg);
        color: var(--error);
      }

      .submit-button {
        border: 0;
        border-radius: var(--radius-md);
        padding: 1rem 1.25rem;
        font: inherit;
        font-weight: 700;
        color: #ffffff;
        background: linear-gradient(135deg, var(--accent), #4a7bff);
        cursor: pointer;
        transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
      }

      .submit-button:hover {
        background: linear-gradient(135deg, var(--accent-strong), var(--accent));
      }

      .submit-button:focus {
        outline: 2px solid transparent;
        box-shadow: 0 0 0 4px rgba(36, 87, 255, 0.18);
      }

      .submit-button:active {
        transform: translateY(1px);
      }

      @media (max-width: 760px) {
        .support-card {
          grid-template-columns: 1fr;
