          border: 1px solid ButtonBorder;
          box-shadow: none;
        }

        .submit-button {
          background: ButtonFace;
          color: ButtonText;
        }

        .feature-dot {
          background: currentColor;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>
    <script>
      const fieldConfig = {
        fullName: {
          id: "fullName",
          label: "Full name",
          type: "text",
          required: true,
          placeholder: "Jordan Lee",
          helperText: "",
        },
        email: {
          id: "email",
          label: "Email address",
          type: "email",
          required: true,
          placeholder: "jordan@example.com",
          helperText: "",
        },
        phone: {
          id: "phone",
          label: "Phone number",
          type: "tel",
          required: false,
          placeholder: "(555) 123-4567",
          helperText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567.",
        },
      };

      const state = {
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
        touched: {
          fullName: false,
          email: false,
          phone: false,
        },
        status: {
          tone: "",
          message: "",
        },
      };

      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;

      function SupportPage() {
        return `
          <div class="page-shell">
            <main id="main-content" class="support-card">
              <section class="support-copy" aria-labelledby="support-heading">
                <p class="eyebrow">Product support</p>
                <h1 id="support-heading">Talk to our support team.</h1>
                <p class="lead">
                  Share a few details and we will route your request to the right specialist.
                  Designed for quick follow-up without extra back-and-forth.
                </p>
                <ul class="feature-list" aria-label="Support benefits">
                  <li><span class="feature-dot" aria-hidden="true"></span><span><strong>Fast triage</strong> for billing, technical, and account issues.</span></li>
                  <li><span class="feature-dot" aria-hidden="true"></span><span><strong>Clear responses</strong> from a team that understands your setup.</span></li>
                  <li><span class="feature-dot" aria-hidden="true"></span><span><strong>Flexible follow-up</strong> by email, with phone contact if you choose.</span></li>
                </ul>
              </section>
              <section class="support-form-panel" aria-labelledby="form-title">
                <h2 id="form-title" class="panel-title">Contact support</h2>
                <p class="panel-copy">Required fields are marked with <span class="required-indicator" aria-hidden="true">*</span>.</p>
                ${ContactForm()}
              </section>
            </main>
          </div>
        `;
      }

      function ContactForm() {
        return `
          <form id="support-form" novalidate>
            ${FormField("fullName")}
            ${FormField("email")}
            ${FormField("phone")}
            <p id="form-status" class="status-message ${state.status.tone}" aria-live="polite">${state.status.message}</p>
            <button class="submit-button" type="submit">Submit request</button>
          </form>
        `;
      }

      function FormField(name) {
        const config = fieldConfig[name];
        const error = getError(name);
        const helperId = config.helperText ? `${config.id}-helper` : "";
        const errorId = `${config.id}-error`;
        const describedBy = [helperId, error ? errorId : ""].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label for="${config.id}">
              ${config.label}${config.required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
            </label>
            <input
              id="${config.id}"
              name="${config.id}"
              type="${config.type}"
              value="${escapeHtml(state.values[name])}"
              placeholder="${config.placeholder}"
              ${config.required ? "required" : ""}
              aria-required="${config.required ? "true" : "false"}"
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
              aria-invalid="${error ? "true" : "false"}"
              autocomplete="${name === "fullName" ? "name" : name === "email" ? "email" : "tel"}"
            />
            ${config.helperText ? `<p id="${helperId}" class="helper-text">${config.helperText}</p>` : ""}
            <p id="${errorId}" class="error-text">${error || ""}</p>
          </div>
        `;
      }

      function getError(name) {
        const value = state.values[name].trim();
        const config = fieldConfig[name];

        if (!state.touched[name]) {
          return "";
        }

        if (config.required && !value) {
          return `${config.label} is required.`;
        }

        if (name === "email" && value && !emailPattern.test(value)) {
          return "Enter a valid email address.";
        }

        if (name === "phone" && value && !phonePattern.test(value)) {
          return "Enter a valid phone number using digits, spaces, parentheses, or dashes.";
        }

        return "";
      }

      function validateAllFields() {
        Object.keys(state.touched).forEach((key) => {
          state.touched[key] = true;
        });

        const entries = Object.keys(fieldConfig).map((name) => [name, getError(name)]);
        return Object.fromEntries(entries);
      }

      function escapeHtml(value) {
        return value
          .replaceAll("&", "&amp;")
          .replaceAll('"', "&quot;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;");
      }

      function render() {
        document.getElementById("app").innerHTML = SupportPage();
        bindEvents();
      }

      function bindEvents() {
        const form = document.getElementById("support-form");

        Object.keys(fieldConfig).forEach((name) => {
          const input = document.getElementById(fieldConfig[name].id);

          input.addEventListener("input", (event) => {
            state.values[name] = event.target.value;

            if (state.touched[name] || state.status.message) {
              state.status = { tone: "", message: "" };
              render();
            }
          });

          input.addEventListener("blur", (event) => {
            state.values[name] = event.target.value;
            state.touched[name] = true;
            render();
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();

          const errors = validateAllFields();
          const firstInvalidName = Object.keys(errors).find((name) => errors[name]);

          if (firstInvalidName) {
            state.status = {
              tone: "error",
              message: "Please correct the highlighted fields and try again.",
            };
            render();
            document.getElementById(fieldConfig[firstInvalidName].id).focus();
            return;
          }

          state.status = {
            tone: "success",
            message: "Thanks. Your support request is ready to be reviewed.",
          };
          render();
          form.reset();
        });
      }

      render();
    </script>
