      const fieldConfig = {
        fullName: {
          id: "fullName",
          label: "Full name",
          type: "text",
          required: true,
          placeholder: "Jordan Lee",
          helperText: "",
        },
        email: {
          id: "email",
          label: "Email address",
          type: "email",
          required: true,
          placeholder: "jordan@example.com",
          helperText: "",
