      function SupportPage() {
        return `
          <div class="page-shell">
            <main id="main-content" class="support-card">
              <section class="support-copy" aria-labelledby="support-heading">
                <p class="eyebrow">Product support</p>
                <h1 id="support-heading">Talk to our support team.</h1>
                <p class="lead">
                  Share a few details and we will route your request to the right specialist.
                  Designed for quick follow-up without extra back-and-forth.
