        const errorId = `${config.id}-error`;
        const describedBy = [helperId, error ? errorId : ""].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label for="${config.id}">
              ${config.label}${config.required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
            </label>
            <input
              id="${config.id}"
              name="${config.id}"
              type="${config.type}"
              value="${escapeHtml(state.values[name])}"
              placeholder="${config.placeholder}"
              ${config.required ? "required" : ""}
              aria-required="${config.required ? "true" : "false"}"
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
              aria-invalid="${error ? "true" : "false"}"
              autocomplete="${name === "fullName" ? "name" : name === "email" ? "email" : "tel"}"
            />
            ${config.helperText ? `<p id="${helperId}" class="helper-text">${config.helperText}</p>` : ""}
            <p id="${errorId}" class="error-text">${error || ""}</p>
          </div>
        `;
