        document.getElementById("app").innerHTML = SupportPage();
        bindEvents();
      }

      function bindEvents() {
        const form = document.getElementById("support-form");

        Object.keys(fieldConfig).forEach((name) => {
          const input = document.getElementById(fieldConfig[name].id);

          input.addEventListener("input", (event) => {
            state.values[name] = event.target.value;

            if (state.touched[name] || state.status.message) {
              state.status = { tone: "", message: "" };
              render();
            }
          });

          input.addEventListener("blur", (event) => {
            state.values[name] = event.target.value;
            state.touched[name] = true;
            render();
          });
        });

