        const config = fieldConfig[name];
        const error = getError(name);
        const helperId = config.helperText ? `${config.id}-helper` : "";
        const errorId = `${config.id}-error`;
        const describedBy = [helperId, error ? errorId : ""].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label for="${config.id}">
              ${config.label}${config.required ? ' <span class="required-indicator" aria-hidden="true">*</span>' : ""}
            </label>
            <input
              id="${config.id}"
              name="${config.id}"
              type="${config.type}"
